const localizedMessages: Record<AppLanguage, Record<keyof typeof messages.en, string>> = {
  en: messages.en,
  "zh-CN": zhCN,
  "zh-TW": zhTW,
};

export type TranslationKey = keyof typeof messages.en;

export function tr(language: AppLanguage, key: TranslationKey, params: TranslationParams = {}): string {
  return localizedMessages[language][key].replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? `{${name}}`));
}

export function localizedUpdateError(language: AppLanguage, message: string): string {
  if (/could not fetch a valid release json from the remote/i.test(message)) return tr(language, "invalidReleaseMetadata");
  return tr(language, "updateCheckFailed");
}

export function localizedDate(language: AppLanguage, value: string | number | Date): string {
  return new Intl.DateTimeFormat(language === "en" ? "en" : language, { dateStyle: "medium" }).format(new Date(value));
}
